public partial class MigrationScene {
 static readonly string[] SuburbNames={"12 / The gardener's house","14 / YOUR HOME","16 / The last breakfast","18 / The volunteer medic","20 / Evacuation night","22 / The radio house","24 / The allotment keeper","26 / The empty nursery"};
 static readonly string[] SuburbNotes={"The garden kept half the street fed. Take what is left. The empty common behind the pump is clear enough to build on.","Left the hand tools in the garage. Find a little scrap, make a screwdriver, then strip the wrecks. Don't waste a good blade on a car.","Three bowls. Two coats. The smallest chair is still pulled out. Whoever left here expected to come back.","Dressings are in the blue locker. Clean the water before you drink it. We moved the serious cases north when the road stopped being safe.","We went house to house. Most doors were already open. There was no one left to ask.","If you hear a dog near the woodland maintenance kennels, it is real. We couldn't open the run before the infected reached us. Follow the old road northwest.","The planting rows are dry, but the seed tins are packed. Someone kept a place ready for spring.","A knitted blanket is folded beside the empty cot. There is no note. There does not need to be."};
 bool InSuburbHome(double x,double z){if(!InBriarLane(x,z))return game.World.ResidentialInterior(x,z);for(int i=0;i<8;i++){var h=SuburbHousePoint(i);if(Math.Abs(x-h.X)<6.1&&Math.Abs(z-h.Z)<6.3)return true;}return false;}
 bool InSuburb(double x,double z)=>game.World.Tier(x,z)==1&&game.World.Playable(x,z);
 bool InBriarLane(double x,double z)=>Math.Abs(x-ExpeditionWorld.SpawnX)<88&&z>ExpeditionWorld.SpawnZ-202&&z<ExpeditionWorld.SpawnZ+45;
 Vector3 SuburbHousePoint(int i)=>Ground(ExpeditionWorld.SpawnX+(i%2==0?-26:26),ExpeditionWorld.SpawnZ-30-(i/2)*42);
 float SuburbHouseFloor(int i){var p=SuburbHousePoint(i);float h=p.Y;foreach(int x in new[]{-7,7})foreach(int z in new[]{-7,7})h=Math.Max(h,(float)game.World.Height(p.X+x,p.Z+z));return h+.05f;}
 Node3D SuburbHouseRoot(int i){var p=SuburbHousePoint(i);p.Y=SuburbHouseFloor(i);return new Node3D{Name="BriarLaneHouse"+i,Position=p,RotationDegrees=new(0,i%2==0?90:-90,0)};}
 bool SuburbPaved(double x,double z){if(!InBriarLane(x,z))return game.World.ResidentialPaved(x,z)||game.World.ResidentialInterior(x,z);double dx=x-ExpeditionWorld.SpawnX;return Math.Abs(dx)<11||Math.Abs(z-(ExpeditionWorld.SpawnZ-173))<6||Enumerable.Range(0,8).Any(i=>{var h=SuburbHousePoint(i);return Math.Abs(x-h.X)<10&&Math.Abs(z-h.Z)<10;});}
 void SuburbChunk(Node3D root,int cx,int cz,bool simulation){
  if(cx*64>ExpeditionWorld.SpawnX+100||(cx+1)*64<game.World.RouteX(ExpeditionWorld.SpawnZ-173)-20||cz*64>ExpeditionWorld.SpawnZ+50||(cz+1)*64<ExpeditionWorld.SpawnZ-205)return;
  if(!simulation){var st=new SurfaceTool();st.Begin(Mesh.PrimitiveType.Triangles);int count=0;for(int x=cx*64;x<(cx+1)*64;x+=2)for(int z=cz*64;z<(cz+1)*64;z+=2){bool connector=x>game.World.RouteX(ExpeditionWorld.SpawnZ-173)&&x<ExpeditionWorld.SpawnX&&Math.Abs(z+1-(ExpeditionWorld.SpawnZ-173))<5;if(!InBriarLane(x+1,z+1)&&!connector)continue;double dx=Math.Abs(x+1-ExpeditionWorld.SpawnX);bool cross=Math.Abs(z+1-(ExpeditionWorld.SpawnZ-173))<5;bool road=game.World.BriarRoad(x+1,z+1),walk=dx>=7&&dx<10;if(!road&&!walk)continue;var c=SurfaceTone(road?2:3);foreach(var p in new[]{SurfaceGround(x,z),SurfaceGround(x+2,z),SurfaceGround(x+2,z+2),SurfaceGround(x,z),SurfaceGround(x+2,z+2),SurfaceGround(x,z+2)}){st.SetColor(c);st.AddVertex(p+Vector3.Up*.045f);}count++;}if(count>0){st.GenerateNormals();root.AddChild(new MeshInstance3D{Mesh=st.Commit(),MaterialOverride=TerrainInk()});}}
  for(int i=0;i<8;i++){var p=SuburbHousePoint(i);if(ExpeditionWorld.Cell(p.X)!=cx||ExpeditionWorld.Cell(p.Z)!=cz)continue;var n=SuburbHouseRoot(i);root.AddChild(n);SuburbHouse(n,i,simulation);}
  for(int i=0;i<8;i++)for(int t=0;t<2;t++){var p=SuburbHousePoint(i);double tx=p.X+(i%2==0?-11:11),tz=p.Z+(t==0?-15:15);if(ExpeditionWorld.Cell(tx)!=cx||ExpeditionWorld.Cell(tz)!=cz)continue;string id=$"suburb/{game.Save.Seed}/tree/{i}/{t}";if(game.World.Changes.Cut(id))continue;var tree=new Node3D{Position=Ground(tx,tz)};root.AddChild(tree);if(simulation)PhysicsObstacle(tree,new CylinderShape3D{Radius=.45f,Height=5},new(0,2.5f,0));else ArtTree(tree,6+(i%3),i*91+t);props.Add(new(){Id=id,Kind=0,Tier=1,Position=tree.Position,Node=tree});}
  for(int row=0;row<8;row++)foreach(int side in new[]{-1,1}){double tx=ExpeditionWorld.SpawnX+side*(row%2==0?53:15),tz=ExpeditionWorld.SpawnZ-12-row*23;if(ExpeditionWorld.Cell(tx)!=cx||ExpeditionWorld.Cell(tz)!=cz)continue;string treeId=$"suburb/{game.Save.Seed}/border/{side}/{row}";if(game.World.Changes.Cut(treeId))continue;var tree=new Node3D{Position=Ground(tx,tz)};root.AddChild(tree);if(simulation)PhysicsObstacle(tree,new CylinderShape3D{Radius=.45f,Height=5},new(0,2.5f,0));else ArtTree(tree,7+row%3,row*53+side);props.Add(new(){Id=treeId,Kind=0,Tier=1,Position=tree.Position,Node=tree});}
  if(simulation)return;
  for(int i=0;i<8;i++){double z=ExpeditionWorld.SpawnZ-12-i*25,x=ExpeditionWorld.SpawnX+(i%2==0?-11:11);if(ExpeditionWorld.Cell(x)!=cx||ExpeditionWorld.Cell(z)!=cz)continue;var p=Ground(x,z);Tube(root,p,p+Vector3.Up*4.6f,.045f,Steel);Tube(root,p+Vector3.Up*4.6f,p+new Vector3(i%2==0?1.3f:-1.3f,4.6f,0),.04f,Steel);Box(root,p+new Vector3(i%2==0?1.3f:-1.3f,4.55f,0),new(.5f,.13f,.3f),new(.65f,.56f,.35f));if(i%3==0)root.AddChild(new OmniLight3D{Position=p+Vector3.Up*4.3f,LightColor=new(1,.71f,.38f),LightEnergy=.35f,OmniRange=9,DistanceFadeEnabled=true,DistanceFadeBegin=45,ShadowEnabled=false});}
 }
 void SuburbHouse(Node3D n,int i,bool simulation){
