  if(i==4){foreach(int side in new[]{-1,1}){Tube(n,new(-7+side*1.3f,0,-8),new(-7,2.4f,-8),.05f,Steel);Tube(n,new(-7+side*.35f,2.2f,-8),new(-7+side*.35f,.65f,-8),.009f,Steel);}Box(n,new(-7,.65f,-8),new(.9f,.08f,.4f),Wood);}
  foreach(int side in new[]{-1,1}){var bin=new Vector3(side*7,.45f,6);Bevel(n,bin,new(.6f,.9f,.6f),new(.20f,.28f,.23f));Box(n,bin+Vector3.Up*.5f,new(.7f,.07f,.7f),Ink);}
  var box=new Vector3(-7,.45f,9);Box(n,box,new(.6f,.65f,.5f),Steel);Tube(n,new(-7,0,9),new(-7,.8f,9),.045f,Wood);
