 void SpawnSuburb(){if(dungeon!=null)return;if(!CoopClient&&NearActiveSurface(Ground(ExpeditionWorld.SpawnX,ExpeditionWorld.SpawnZ-160),120))for(int j=0;j<2;j++){string enemy="story/suburb/"+j;AddEnemy(enemy,ExpeditionWorld.SpawnX+(j==0?-13:16),ExpeditionWorld.SpawnZ-144-j*22,1);}for(int i=0;i<8;i++){var home=SuburbHousePoint(i);if(!NearActiveSurface(home,210))continue;string wreck=$"suburb/{game.Save.Seed}/wreck/{i}";if(uniqueObjects.Add(wreck)){var tr=SuburbHouseRoot(i);var wp=tr.Transform*new Vector3(BriarCarSide,0,-1);tr.Free();wp.Y=(float)game.World.Height(wp.X,wp.Z);var car=new Node3D{Position=wp,RotationDegrees=new(0,i%2==0?90:-90,0)};worldRoot.AddChild(car);GroundVehicle(car);wp=car.GlobalPosition;bool burned=game.World.Changes.Burned(wreck);ArtWreck(car,burned);PhysicsObstacle(car,new BoxShape3D{Size=new(2.1f,1.5f,4.2f)},new(0,.75f,0));props.Add(new(){Id=wreck,Kind=2,Node=car,Position=wp,Hp=burned?0:100});}string id=$"suburb/{game.Save.Seed}/cache/{i}";if(uniqueObjects.Contains(id)||game.World.Changes.OpenedSalvage.Contains(id))continue;var transform=SuburbHouseRoot(i);var point=transform.Transform*new Vector3(2.8f,.16f,1.3f);transform.Free();var n=new Node3D{Position=point};worldRoot.AddChild(n);int kind=i==1?4:i==3?2:0;DressSalvage(n,kind);props.Add(new(){Id=id,Kind=15,Node=n,Position=point,Material=kind,Tier=1});uniqueObjects.Add(id);}
 }
 void ShowSuburbGuide(){var b=Panel("BRIAR LANE / THE LAST QUIET STREET");Text(b,"Start close to home. The sealed water carrier is beside the lane. Search the houses for food and dressings; the garage has timber, stone and the first scrap for your tools. Branches and flax are scattered through the common. Chop its pines and make a shelter before following the road northwest.\n\nYour house is your settlement home. Put survivor cots inside, improve the yard, and use other shelters as outposts. Dismantle furniture in other houses with F or an axe for scrap and reclaimed materials. The farther you explore from home, the more infected gather. No timed opening raid.");for(int i=0;i<8;i++){int index=i;Text(b,SuburbNames[i]+"\n"+SuburbNotes[i]);var p=SuburbHousePoint(i);LocationButton(b,SuburbNames[index],p.X,p.Z,ShowSuburbGuide);}LocationButton(b,"Buildable common / pump and pines",ExpeditionWorld.SpawnX-25,ExpeditionWorld.SpawnZ+10,ShowSuburbGuide);Button(b,"BACK TO FIRST DAY",()=>ShowFirstDay());}
